#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BUTTON1_PIN = 2; 
const int BUTTON2_PIN = 3; 
const int RGB_RED_PIN = 4; 
const int RGB_GREEN_PIN = 5; 
const int RGB_BLUE_PIN = 6; 
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000, 
};
int currentNumber = 0;
unsigned long lastDebounceTime1 = 0; 
unsigned long lastDebounceTime2 = 0; 
const unsigned long debounceDelay = 50; 
bool button1State = HIGH; 
bool button2State = HIGH; 
bool lastButton1State = HIGH; 
bool lastButton2State = HIGH; 

void setup();
void loop();
void displayNumber(int number);
void updateRGB(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);
  pinMode(RGB_RED_PIN, OUTPUT);
  pinMode(RGB_GREEN_PIN, OUTPUT);
  pinMode(RGB_BLUE_PIN, OUTPUT);
  displayNumber(currentNumber);
  updateRGB(currentNumber);
}
void loop() {
  int reading1 = digitalRead(BUTTON1_PIN); 
  int reading2 = digitalRead(BUTTON2_PIN); 
  if (reading1 != lastButton1State) {
    lastDebounceTime1 = millis(); 
  }
  if ((millis() - lastDebounceTime1) > debounceDelay) {
    if (reading1 != button1State) {
      button1State = reading1;
      if (button1State == LOW) { 
        currentNumber = (currentNumber + 1) % 100; 
        displayNumber(currentNumber);
        updateRGB(currentNumber);
      }
    }
  }
  lastButton1State = reading1; 
  if (reading2 != lastButton2State) {
    lastDebounceTime2 = millis(); 
  }
  if ((millis() - lastDebounceTime2) > debounceDelay) {
    if (reading2 != button2State) {
      button2State = reading2;
      if (button2State == LOW) { 
        currentNumber = (currentNumber - 1 + 100) % 100; 
        displayNumber(currentNumber);
        updateRGB(currentNumber);
      }
    }
  }
  lastButton2State = reading2; 
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void updateRGB(int number) {
  if (number >= 0 && number <= 33) {
    analogWrite(RGB_RED_PIN, 255); 
    analogWrite(RGB_GREEN_PIN, 0);
    analogWrite(RGB_BLUE_PIN, 0);
  } else if (number >= 34 && number <= 66) {
    analogWrite(RGB_RED_PIN, 0);
    analogWrite(RGB_GREEN_PIN, 255); 
    analogWrite(RGB_BLUE_PIN, 0);
  } else if (number >= 67 && number <= 99) {
    analogWrite(RGB_RED_PIN, 0);
    analogWrite(RGB_GREEN_PIN, 0);
    analogWrite(RGB_BLUE_PIN, 255); 
  }
}
